"""Expression extraction and parsing."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Literal, Sequence

import sympy as sp
from latex2sympy2_extended import NormalizationConfig, latex2sympy, normalize_latex
from sympy import Basic
from sympy.core.relational import Relational
from sympy.matrices import MatrixBase
from sympy.parsing.sympy_parser import (
    convert_xor,
    implicit_multiplication_application,
    parse_expr,
    standard_transformations,
)

from .errors import ParseTimeoutError
from .utils import time_limit, unique_in_order

ParsedValue = Basic | MatrixBase | str

_TRANSFORMATIONS = standard_transformations + (
    implicit_multiplication_application,
    convert_xor,
)
_ANSWER_PREFIX_RE = re.compile(
    r"(?is)^\s*(?:\*\*+\s*)?(?:final\s+answer|answer|therefore|thus|hence|so|result|value|probability|domain|number)"
    r"(?:\s+is|\s*=|:)?\s*"
)
_ANCHOR_RE = re.compile(
    r"(?i)(?:final\s+answer|answer(?:\s+is)?|therefore|thus|hence|result(?:\s+is)?|value(?:\s+is)?|"
    r"probability(?:\s+is)?|domain(?:\s+is)?|number(?:\s+is)?)"
)
_CURRENCY_CHARS = "$€£¥₹"
_UNIT_SUFFIX_RE = re.compile(
    r"(?<=\d)\s*(?:m²|cm²|mm²|km²|m|cm|mm|km|meters?|metres?|centimeters?|centimetres?|"
    r"millimeters?|millimetres?|kilometers?|kilometres?|feet|foot|ft|inches?|inch|yards?|yd|"
    r"degrees?|°|radians?|hours?|hrs?|minutes?|mins?|seconds?|secs?|kg|g|lbs?|lb)\b",
    re.IGNORECASE,
)
_TEXT_BLOCK_RE = re.compile(r"\\text\s*\{[^{}]*\}")
_PERCENT_RE = re.compile(r"(?is)^\s*(.+?)\s*(?:\\%|%|percent|pct)\s*$")
_NUMBER_RE = re.compile(
    r"(?<![A-Za-z0-9_])"
    r"[+-]?(?:[$€£¥₹]\s*)?(?:\d[\d,\s]*(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?"
    r"(?:\s*(?:m²|cm²|mm²|km²|m|cm|mm|km|meters?|metres?|centimeters?|centimetres?|"
    r"millimeters?|millimetres?|kilometers?|kilometres?|degrees?|°|pct|percent))?"
    r"(?![A-Za-z_])"
)
_LATEX_CMDS_TO_PLAIN = (
    (r"\leq", "<="),
    (r"\le", "<="),
    (r"\geq", ">="),
    (r"\ge", ">="),
    (r"\neq", "!="),
    (r"\ne", "!="),
    (r"\cup", " ∪ "),
    (r"\cap", " ∩ "),
    (r"\infty", "oo"),
    (r"\pi", "pi"),
)


@dataclass(frozen=True)
class LatexNormalizationConfig:
    basic_latex: bool = True
    units: bool = False
    malformed_operators: bool = True
    nits: bool = False
    boxed: Literal["all", "last", "none"] = "all"

    def to_external(self) -> NormalizationConfig:
        return NormalizationConfig(
            basic_latex=self.basic_latex,
            units=self.units,
            malformed_operators=self.malformed_operators,
            nits=self.nits,
            boxed=self.boxed,
        )


@dataclass(frozen=True)
class LatexExtractionConfig:
    try_extract_without_anchor: bool = True
    boxed_match_priority: int = 50
    extract_last_expression: bool = False
    normalization_config: LatexNormalizationConfig = field(default_factory=LatexNormalizationConfig)


@dataclass(frozen=True)
class ExprExtractionConfig:
    try_extract_without_anchor: bool = True
    extract_last_expression: bool = False


@dataclass(frozen=True)
class StringExtractionConfig:
    strings: tuple[str, ...] = ("A", "B", "C", "D")
    try_extract_without_anchor: bool = True
    lowercase: bool = True


ExtractionTarget = LatexExtractionConfig | ExprExtractionConfig | StringExtractionConfig
DEFAULT_EXTRACTION_CONFIG: tuple[ExtractionTarget, ...] = (
    LatexExtractionConfig(),
    ExprExtractionConfig(),
)


def parse(
    pred: str,
    extraction_config: Sequence[ExtractionTarget] = DEFAULT_EXTRACTION_CONFIG,
    fallback_mode: Literal["no_fallback", "first_match"] = "first_match",
    extraction_mode: Literal["first_match", "any_match"] = "any_match",
    parsing_timeout: int | None = 5,
) -> list[ParsedValue]:
    """Extract and parse mathematical answers from free-form text."""

    if not pred or not pred.strip():
        return []

    configs = tuple(extraction_config) if extraction_config else DEFAULT_EXTRACTION_CONFIG
    first_raw_match: str | None = None

    for config in configs:
        if isinstance(config, StringExtractionConfig):
            string_match = _extract_string_match(pred, config)
            if string_match:
                return string_match
            continue

        if isinstance(config, LatexExtractionConfig):
            candidates = _extract_latex_candidates(pred, config)
            parser = lambda candidate: _parse_latex_candidate(candidate, config, parsing_timeout)
        else:
            candidates = _extract_expr_candidates(pred, config)
            parser = lambda candidate: _parse_expr_candidate(candidate, parsing_timeout)

        if candidates and first_raw_match is None:
            first_raw_match = candidates[0]

        parsed_values: list[ParsedValue] = []
        for candidate in candidates:
            parsed = parser(candidate)
            if parsed is None:
                continue
            parsed_values.append(parsed)
            if extraction_mode == "first_match":
                return unique_in_order(parsed_values)

        parsed_values = unique_in_order(parsed_values)
        if parsed_values:
            return parsed_values

    if fallback_mode == "first_match" and first_raw_match is not None:
        return [first_raw_match]
    return []


def _extract_string_match(text: str, config: StringExtractionConfig) -> list[str]:
    if not text.strip():
        return []
    tokens = sorted(config.strings, key=len, reverse=True)
    pattern = "|".join(re.escape(token) for token in tokens)
    match = re.search(rf"(?i)\b({pattern})\b", text)
    if not match:
        return []
    original = next(token for token in config.strings if token.lower() == match.group(1).lower())
    normalized = original.lower() if config.lowercase else original
    return [normalized, original]


def _extract_latex_candidates(text: str, config: LatexExtractionConfig) -> list[str]:
    candidates: list[tuple[int, int, str]] = []
    anchor_end = _last_anchor_end(text)

    if config.boxed_match_priority >= 0:
        for start, content in _find_boxed_segments(text):
            priority = config.boxed_match_priority - (25 if anchor_end >= 0 and start >= anchor_end else 0)
            candidates.append((priority, start, content.strip()))

    for start, content in _find_math_delimited_segments(text):
        priority = 40 - (20 if anchor_end >= 0 and start >= anchor_end else 0)
        candidates.append((priority, start, content.strip()))

    if config.try_extract_without_anchor:
        if anchor_end >= 0:
            tail = text[anchor_end:].strip()
            if tail:
                candidates.append((25, anchor_end, tail))
        if _looks_like_latex(text):
            candidates.append((70, len(text), text.strip()))

    candidates = _dedupe_candidates(candidates, reverse=not config.extract_last_expression)
    return [candidate for _, _, candidate in candidates]


def _extract_expr_candidates(text: str, config: ExprExtractionConfig) -> list[str]:
    candidates: list[tuple[int, int, str]] = []
    anchor_end = _last_anchor_end(text)

    if anchor_end >= 0:
        tail = text[anchor_end:].strip()
        if tail:
            candidates.append((0, anchor_end, tail))

    for line in [line.strip() for line in text.splitlines() if line.strip()]:
        start = text.rfind(line)
        candidates.append((10, start, line))

    clauses = [
        clause.strip()
        for clause in re.split(r"(?:[.;]|(?<=\))\s*,\s*(?=\())", text)
        if clause.strip()
    ]
    for clause in clauses:
        start = text.rfind(clause)
        candidates.append((20, start, clause))

    for match in _NUMBER_RE.finditer(text):
        candidates.append((30, match.start(), match.group(0)))

    candidates.append((50, len(text), text.strip()))
    candidates = _dedupe_candidates(candidates, reverse=not config.extract_last_expression)
    return [candidate for _, _, candidate in candidates]


def _dedupe_candidates(
    candidates: list[tuple[int, int, str]],
    *,
    reverse: bool,
) -> list[tuple[int, int, str]]:
    ordered: list[tuple[int, int, str]] = []
    seen: set[str] = set()
    sort_key = lambda item: (item[0], -item[1] if reverse else item[1])
    for item in sorted(candidates, key=sort_key):
        cleaned = item[2].strip()
        if not cleaned or cleaned in seen:
            continue
        seen.add(cleaned)
        ordered.append((item[0], item[1], cleaned))
    return ordered


def _find_math_delimited_segments(text: str) -> list[tuple[int, str]]:
    patterns = (
        re.compile(r"\$\$(.+?)\$\$", re.DOTALL),
        re.compile(r"(?<!\$)\$(?!\$)(.+?)(?<!\\)\$(?!\$)", re.DOTALL),
        re.compile(r"\\\((.+?)\\\)", re.DOTALL),
        re.compile(r"\\\[(.+?)\\\]", re.DOTALL),
    )
    results: list[tuple[int, str]] = []
    for pattern in patterns:
        for match in pattern.finditer(text):
            results.append((match.start(), match.group(1)))
    return results


def _find_boxed_segments(text: str) -> list[tuple[int, str]]:
    results: list[tuple[int, str]] = []
    for match in re.finditer(r"\\(?:boxed|fbox)\s*\{", text):
        open_index = match.end() - 1
        close_index = _find_matching_brace(text, open_index)
        if close_index < 0:
            continue
        results.append((match.start(), text[open_index + 1 : close_index]))
    return results


def _find_matching_brace(text: str, open_index: int) -> int:
    depth = 0
    for index in range(open_index, len(text)):
        if text[index] == "{":
            depth += 1
        elif text[index] == "}":
            depth -= 1
            if depth == 0:
                return index
    return -1


def _last_anchor_end(text: str) -> int:
    matches = list(_ANCHOR_RE.finditer(text))
    return matches[-1].end() if matches else -1


def _looks_like_latex(text: str) -> bool:
    return "\\" in text or bool(re.search(r"[$^_{}]|\\begin\{", text))


def _parse_latex_candidate(
    candidate: str,
    config: LatexExtractionConfig,
    parsing_timeout: int | None,
) -> ParsedValue | None:
    stripped = _strip_outer_math_wrappers(candidate)
    if not stripped:
        return None
    if config.boxed_match_priority < 0 and re.fullmatch(r"\\(?:boxed|fbox)\s*\{.*\}", stripped, re.DOTALL):
        return None

    cleaned = _clean_latex_candidate(stripped)
    if not cleaned:
        return None

    percent_value = _parse_percentage(cleaned, parsing_timeout)
    if percent_value is not None:
        return percent_value

    custom_value = _parse_collection_or_relation(_latexish_to_plain(cleaned), parsing_timeout)
    if custom_value is not None:
        return _postprocess_parsed_value(custom_value)

    try:
        normalized = normalize_latex(cleaned, config.normalization_config.to_external())
        with time_limit(parsing_timeout, ParseTimeoutError, "LaTeX parsing timed out"):
            parsed = latex2sympy(normalized, normalization_config=config.normalization_config.to_external())
    except (Exception, ParseTimeoutError):
        return _parse_expression_text(_latexish_to_plain(cleaned), parsing_timeout)
    return _postprocess_parsed_value(parsed)


def _parse_expr_candidate(candidate: str, parsing_timeout: int | None) -> ParsedValue | None:
    return _parse_expression_text(candidate, parsing_timeout)


def _parse_expression_text(text: str, parsing_timeout: int | None) -> ParsedValue | None:
    prepared = _prepare_common_text(text)
    if not prepared or not _contains_math_signal(prepared):
        return None

    fragments = [prepared]
    fragments.extend(_fragment_candidates(prepared))

    for fragment in unique_in_order(fragments):
        parsed = _parse_expression_core(fragment, parsing_timeout)
        if parsed is not None:
            return _postprocess_parsed_value(parsed)
    return None


def _parse_expression_core(text: str, parsing_timeout: int | None) -> Basic | MatrixBase | None:
    cleaned = _strip_outer_math_wrappers(text)
    cleaned = _prepare_common_text(cleaned)
    if not cleaned:
        return None

    percent_value = _parse_percentage(cleaned, parsing_timeout)
    if percent_value is not None:
        return percent_value

    collection_value = _parse_collection_or_relation(cleaned, parsing_timeout)
    if collection_value is not None:
        return collection_value

    if _looks_like_latex(cleaned):
        try:
            normalized = normalize_latex(_clean_latex_candidate(cleaned), LatexNormalizationConfig().to_external())
            with time_limit(parsing_timeout, ParseTimeoutError, "LaTeX parsing timed out"):
                parsed = latex2sympy(normalized, normalization_config=LatexNormalizationConfig().to_external())
            return parsed
        except (Exception, ParseTimeoutError):
            pass

    expression_text = _normalize_expression_text(cleaned)
    if not expression_text:
        return None
    try:
        local_dict = _build_local_dict(expression_text)
        with time_limit(parsing_timeout, ParseTimeoutError, "Expression parsing timed out"):
            parsed = parse_expr(
                expression_text,
                local_dict=local_dict,
                transformations=_TRANSFORMATIONS,
                evaluate=True,
            )
    except (Exception, ParseTimeoutError):
        return None
    return parsed


def _parse_percentage(text: str, parsing_timeout: int | None) -> Basic | None:
    match = _PERCENT_RE.fullmatch(text.replace("$", "").strip())
    if not match:
        return None
    base = _parse_expression_core(match.group(1), parsing_timeout)
    if base is None:
        return None
    try:
        return sp.simplify(base / 100)
    except Exception:
        return None


def _parse_collection_or_relation(text: str, parsing_timeout: int | None) -> Basic | MatrixBase | None:
    plain = _latexish_to_plain(text).strip()
    if not plain:
        return None

    if "∪" in plain or " union " in plain.lower():
        separator = "∪" if "∪" in plain else re.search(r"(?i)\bunion\b", plain).group(0)
        parts = _split_top_level(plain, separator)
        parsed_parts = []
        for part in parts:
            parsed_part = _parse_collection_or_relation(part, parsing_timeout) or _parse_expression_core(part, parsing_timeout)
            if parsed_part is None:
                return None
            parsed_parts.append(_as_set(parsed_part))
        try:
            return sp.Union(*parsed_parts)
        except Exception:
            return None

    if "∩" in plain or " intersection " in plain.lower():
        separator = "∩" if "∩" in plain else re.search(r"(?i)\bintersection\b", plain).group(0)
        parts = _split_top_level(plain, separator)
        parsed_parts = []
        for part in parts:
            parsed_part = _parse_collection_or_relation(part, parsing_timeout) or _parse_expression_core(part, parsing_timeout)
            if parsed_part is None:
                return None
            parsed_parts.append(_as_set(parsed_part))
        try:
            return sp.Intersection(*parsed_parts)
        except Exception:
            return None

    finite_set = _parse_finite_set(plain, parsing_timeout)
    if finite_set is not None:
        return finite_set

    interval_or_tuple = _parse_interval_or_tuple(plain, parsing_timeout)
    if interval_or_tuple is not None:
        return interval_or_tuple

    relation = _parse_relation(plain, parsing_timeout)
    if relation is not None:
        return relation

    tuple_collection = _parse_multiple_parenthesized_tuples(plain, parsing_timeout)
    if tuple_collection is not None:
        return tuple_collection

    return None


def _parse_finite_set(text: str, parsing_timeout: int | None) -> Basic | None:
    if not (text.startswith("{") and text.endswith("}")):
        return None
    inner = text[1:-1].strip()
    if not inner:
        return sp.EmptySet
    parts = _split_top_level(inner, ",")
    items = []
    for part in parts:
        parsed = _parse_expression_core(part, parsing_timeout)
        if parsed is None:
            return None
        items.append(_set_hashable(parsed))
    return sp.FiniteSet(*items)


def _parse_interval_or_tuple(text: str, parsing_timeout: int | None) -> Basic | None:
    if not text or text[0] not in "([{" or text[-1] not in ")]}":
        return None
    if text[0] == "{" and text[-1] == "}":
        return None

    inner = text[1:-1].strip()
    parts = _split_top_level(inner, ",")
    if len(parts) < 2:
        return None

    parsed_parts = [_parse_expression_core(part, parsing_timeout) for part in parts]
    if any(part is None for part in parsed_parts):
        return None

    if len(parsed_parts) != 2:
        return sp.Tuple(*parsed_parts)

    left, right = parsed_parts
    if _should_treat_as_interval(text[0], text[-1], left, right):
        return _build_interval(left, right, text[0], text[-1])
    return sp.Tuple(left, right)


def _parse_multiple_parenthesized_tuples(text: str, parsing_timeout: int | None) -> Basic | None:
    groups = [group.strip() for group in _split_top_level(text, ",") if group.strip()]
    if len(groups) < 2 or not all(group.startswith("(") and group.endswith(")") for group in groups):
        return None
    parsed_groups = []
    for group in groups:
        parsed = _parse_interval_or_tuple(group, parsing_timeout)
        if parsed is None:
            return None
        parsed_groups.append(_set_hashable(parsed))
    return sp.FiniteSet(*parsed_groups)


def _parse_relation(text: str, parsing_timeout: int | None) -> Basic | None:
    normalized = _normalize_relation_text(text)
    if not _contains_relation(normalized):
        return None

    or_parts = re.split(r"(?i)\bor\b", normalized)
    if len(or_parts) > 1:
        rhs_values = []
        lhs_value = None
        for part in or_parts:
            parsed = _parse_relation(part.strip(), parsing_timeout)
            if not isinstance(parsed, sp.Equality):
                return None
            if lhs_value is None:
                lhs_value = parsed.lhs
            elif sp.simplify(lhs_value - parsed.lhs) != 0:
                return None
            rhs_values.append(_set_hashable(parsed.rhs))
        return sp.FiniteSet(*rhs_values)

    if "=" in normalized and not any(op in normalized for op in ("<=", ">=", "!=", "==")):
        lhs_text, rhs_text = _split_first_top_level(normalized, "=")
        if lhs_text is None or rhs_text is None:
            return None
        lhs = _parse_expression_core(lhs_text, parsing_timeout)
        rhs = _parse_expression_core(rhs_text, parsing_timeout)
        if lhs is None or rhs is None:
            return None
        if _is_simple_assignment_lhs(lhs):
            return rhs
        return sp.Eq(lhs, rhs)

    expr_text = _normalize_expression_text(normalized)
    try:
        with time_limit(parsing_timeout, ParseTimeoutError, "Expression parsing timed out"):
            return parse_expr(
                expr_text,
                local_dict=_build_local_dict(expr_text),
                transformations=_TRANSFORMATIONS,
                evaluate=False,
            )
    except (Exception, ParseTimeoutError):
        return None


def _normalize_relation_text(text: str) -> str:
    result = text
    for source, target in _LATEX_CMDS_TO_PLAIN:
        result = result.replace(source, target)
    result = result.replace("≤", "<=").replace("≥", ">=").replace("≠", "!=")
    return result


def _contains_relation(text: str) -> bool:
    return any(op in text for op in ("<=", ">=", "!=", "=", "<", ">"))


def _is_simple_assignment_lhs(value: Basic | MatrixBase) -> bool:
    return isinstance(value, Basic) and (value.is_Symbol or value.is_Function)


def _build_interval(left: Basic, right: Basic, opener: str, closer: str) -> Basic:
    left_open = opener == "("
    right_open = closer == ")"
    swap_needed = _compare_numeric_values(left, right)
    if swap_needed is True:
        left, right = right, left
        left_open, right_open = right_open, left_open
    return sp.Interval(left, right, left_open=left_open, right_open=right_open)


def _should_treat_as_interval(opener: str, closer: str, left: Basic, right: Basic) -> bool:
    if opener == "[" or closer == "]":
        return True
    if not (opener == "(" and closer == ")"):
        return False
    comparison = _compare_numeric_values(left, right)
    return comparison is False


def _compare_numeric_values(left: Basic, right: Basic) -> bool | None:
    try:
        if left.free_symbols or right.free_symbols:
            return None
    except AttributeError:
        return None
    try:
        left_value = complex(sp.N(left, 30))
        right_value = complex(sp.N(right, 30))
    except Exception:
        return None
    if left_value.real > right_value.real:
        return True
    if left_value.real < right_value.real:
        return False
    return None


def _as_set(value: Basic | MatrixBase) -> Basic:
    if isinstance(value, sp.Set):
        return value
    return sp.FiniteSet(_set_hashable(value))


def _set_hashable(value: Basic | MatrixBase) -> Basic:
    if isinstance(value, MatrixBase):
        return sp.ImmutableMatrix(value)
    return value


def _fragment_candidates(text: str) -> list[str]:
    fragments: list[str] = []

    relation_fragments = re.findall(r"[A-Za-z0-9_\\{}()[\],.+\-*/^ ]*(?:<=|>=|<|>|=|!=)[A-Za-z0-9_\\{}()[\],.+\-*/^ ]+", text)
    fragments.extend(fragment.strip() for fragment in relation_fragments if fragment.strip())

    for start, end in _balanced_spans(text):
        fragment = text[start:end]
        if fragment.strip():
            fragments.append(fragment.strip())

    fragments.extend(match.group(0).strip() for match in _NUMBER_RE.finditer(text))
    return list(reversed(unique_in_order(fragments)))


def _balanced_spans(text: str) -> list[tuple[int, int]]:
    stack: list[tuple[str, int]] = []
    spans: list[tuple[int, int]] = []
    matching = {")": "(", "]": "[", "}": "{"}
    for index, char in enumerate(text):
        if char in "([{":
            stack.append((char, index))
        elif char in ")]}" and stack and stack[-1][0] == matching[char]:
            _, start = stack.pop()
            spans.append((start, index + 1))
    return spans


def _prepare_common_text(text: str) -> str:
    cleaned = text.replace("\u2212", "-").replace("\u2013", "-").replace("\u2014", "-")
    cleaned = cleaned.replace("\u00d7", "*").replace("\u00f7", "/").replace("\u22c5", "*")
    cleaned = cleaned.replace("∞", "oo").replace("π", "pi")
    cleaned = cleaned.replace("**", " ")
    cleaned = _ANSWER_PREFIX_RE.sub("", cleaned).strip()
    cleaned = cleaned.strip(" \n\t")
    cleaned = re.sub(r"\s+", " ", cleaned)
    return cleaned


def _clean_latex_candidate(text: str) -> str:
    cleaned = _TEXT_BLOCK_RE.sub("", text)
    cleaned = cleaned.replace(r"\left", "").replace(r"\right", "")
    cleaned = cleaned.replace(r"\$", " ")
    cleaned = cleaned.strip()
    return cleaned


def _latexish_to_plain(text: str) -> str:
    result = text
    for source, target in _LATEX_CMDS_TO_PLAIN:
        result = result.replace(source, target)
    result = result.replace(r"\{", "{").replace(r"\}", "}")
    result = result.replace(r"\(", "(").replace(r"\)", ")").replace(r"\[", "[").replace(r"\]", "]")
    result = result.replace(r"\pm", " ± ")
    result = result.replace(r"\%", "%")
    return result


def _strip_outer_math_wrappers(text: str) -> str:
    stripped = text.strip().rstrip(".,;:")
    wrappers = (
        (r"\(", r"\)"),
        (r"\[", r"\]"),
        ("$$", "$$"),
        ("$", "$"),
    )
    for opener, closer in wrappers:
        if stripped.startswith(opener) and stripped.endswith(closer) and len(stripped) > len(opener) + len(closer):
            stripped = stripped[len(opener) : -len(closer)].strip()
    return stripped.strip()


def _normalize_expression_text(text: str) -> str:
    cleaned = text
    cleaned = cleaned.replace("^", "**")
    cleaned = cleaned.replace("∪", " | ").replace("∩", " & ")
    cleaned = cleaned.replace("±", " ")
    cleaned = cleaned.translate(str.maketrans("", "", _CURRENCY_CHARS))
    cleaned = _UNIT_SUFFIX_RE.sub("", cleaned)
    cleaned = _normalize_numeric_literals(cleaned)
    cleaned = cleaned.strip()
    return cleaned


def _normalize_numeric_literals(text: str) -> str:
    def repl(match: re.Match[str]) -> str:
        return _normalize_numeric_literal(match.group(0))

    return _NUMBER_RE.sub(repl, text)


def _normalize_numeric_literal(token: str) -> str:
    cleaned = token.strip().replace(" ", "")
    while cleaned and cleaned[0] in _CURRENCY_CHARS:
        cleaned = cleaned[1:]
    cleaned = re.sub(r"(?i)(pct|percent)$", "", cleaned)
    cleaned = _UNIT_SUFFIX_RE.sub("", cleaned)
    sign = ""
    if cleaned.startswith(("+", "-")):
        sign, cleaned = cleaned[0], cleaned[1:]
    if cleaned.startswith("."):
        cleaned = "0" + cleaned
    if "," in cleaned and "." in cleaned:
        if cleaned.rfind(",") > cleaned.rfind("."):
            cleaned = cleaned.replace(".", "").replace(",", ".")
        else:
            cleaned = cleaned.replace(",", "")
    elif "," in cleaned:
        parts = cleaned.split(",")
        if len(parts) > 2 and all(len(part) == 3 for part in parts[1:]):
            cleaned = "".join(parts)
        elif len(parts) == 2 and len(parts[1]) in (1, 2):
            cleaned = ".".join(parts)
        elif len(parts) == 2 and len(parts[1]) == 3 and len(parts[0]) > 3:
            cleaned = ".".join(parts)
        else:
            cleaned = "".join(parts)
    if cleaned.isdigit():
        cleaned = str(int(cleaned))
    return sign + cleaned


def _contains_math_signal(text: str) -> bool:
    return bool(re.search(r"[0-9]|\\|[%<>=+\-*/^{}()[\]]", text))


def _split_top_level(text: str, delimiter: str) -> list[str]:
    parts: list[str] = []
    depth = 0
    start = 0
    i = 0
    while i < len(text):
        char = text[i]
        if char in "([{":
            depth += 1
        elif char in ")]}":
            depth = max(0, depth - 1)
        if depth == 0 and text.startswith(delimiter, i):
            parts.append(text[start:i].strip())
            i += len(delimiter)
            start = i
            continue
        i += 1
    parts.append(text[start:].strip())
    return [part for part in parts if part]


def _split_first_top_level(text: str, delimiter: str) -> tuple[str | None, str | None]:
    depth = 0
    for index, char in enumerate(text):
        if char in "([{":
            depth += 1
        elif char in ")]}":
            depth = max(0, depth - 1)
        elif depth == 0 and text.startswith(delimiter, index):
            return text[:index].strip(), text[index + len(delimiter) :].strip()
    return None, None


def _build_local_dict(expression: str) -> dict[str, object]:
    local_dict: dict[str, object] = {
        "Eq": sp.Eq,
        "And": sp.And,
        "Or": sp.Or,
        "Interval": sp.Interval,
        "Union": sp.Union,
        "Intersection": sp.Intersection,
        "FiniteSet": sp.FiniteSet,
        "Tuple": sp.Tuple,
        "Matrix": sp.Matrix,
        "oo": sp.oo,
        "pi": sp.pi,
        "E": sp.E,
        "I": sp.I,
    }
    names = set(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", expression))
    call_names = set(re.findall(r"([A-Za-z_][A-Za-z0-9_]*)\s*\(", expression))
    for name in names:
        if name in local_dict:
            continue
        if hasattr(sp, name):
            local_dict[name] = getattr(sp, name)
            continue
        if name in call_names:
            local_dict[name] = sp.Function(name)
        else:
            local_dict[name] = sp.Symbol(name, real=True)
    return local_dict


def _postprocess_parsed_value(value: Basic | MatrixBase | object) -> ParsedValue | None:
    if value is None:
        return None
    if isinstance(value, MatrixBase):
        return value
    if not isinstance(value, Basic):
        return None
    if isinstance(value, sp.Equality) and _is_simple_assignment_lhs(value.lhs):
        return value.rhs
    if isinstance(value, Relational):
        return value.canonical
    if isinstance(value, sp.Tuple) and len(value) == 2 and all(isinstance(item, Basic) for item in value):
        return value
    return sp.simplify(value)

