"""SymPy expression comparison strategies."""

from __future__ import annotations

from itertools import permutations

import sympy as sp
from sympy import Basic
from sympy.core.relational import Relational
from sympy.logic.boolalg import And, Boolean, Or
from sympy.matrices import MatrixBase


def sympy_expr_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    """Compare two SymPy objects using symbolic, numeric, and structural checks."""

    if not strict:
        gold = _canonicalize_free_symbols(gold)
        target = _canonicalize_free_symbols(target)

    if gold == target:
        return True

    if isinstance(gold, MatrixBase) or isinstance(target, MatrixBase):
        return _matrix_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if _is_set_like(gold) or _is_set_like(target):
        return _set_like_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if _is_relation_like(gold) or _is_relation_like(target):
        return _relation_like_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if isinstance(gold, sp.Tuple) or isinstance(target, sp.Tuple):
        return _tuple_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if isinstance(gold, sp.Equality) and isinstance(target, sp.Equality):
        return _equation_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if isinstance(gold, sp.Equality) and _is_simple_assignment_lhs(gold.lhs):
        return sympy_expr_eq(gold.rhs, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    if isinstance(target, sp.Equality) and _is_simple_assignment_lhs(target.lhs):
        return sympy_expr_eq(gold, target.rhs, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if _numeric_eq(gold, target, float_rounding, numeric_precision):
        return True

    try:
        if sp.simplify(gold - target) == 0:
            return True
    except Exception:
        pass

    try:
        if bool(gold.equals(target)):
            return True
    except Exception:
        pass

    return False


def _canonicalize_free_symbols(value: Basic | MatrixBase) -> Basic | MatrixBase:
    if isinstance(value, MatrixBase):
        mapping = _symbol_mapping(value.free_symbols)
        return value.applyfunc(lambda item: item.xreplace(mapping))
    if not isinstance(value, Basic):
        return value
    return value.xreplace(_symbol_mapping(value.free_symbols))


def _symbol_mapping(symbols: set[sp.Symbol]) -> dict[sp.Symbol, sp.Symbol]:
    ordered = sorted(symbols, key=lambda symbol: symbol.sort_key())
    return {symbol: sp.Symbol(f"_v{i}", real=symbol.is_real) for i, symbol in enumerate(ordered)}


def _matrix_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    if not isinstance(gold, MatrixBase) or not isinstance(target, MatrixBase):
        return False
    if gold.shape != target.shape:
        return False
    for left, right in zip(gold, target):
        if not sympy_expr_eq(left, right, float_rounding, numeric_precision, allow_set_relation_comp, strict):
            return False
    return True


def _tuple_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    if not isinstance(gold, sp.Tuple) or not isinstance(target, sp.Tuple):
        return False
    if len(gold) != len(target):
        return False
    return all(
        sympy_expr_eq(left, right, float_rounding, numeric_precision, allow_set_relation_comp, strict)
        for left, right in zip(gold, target)
    )


def _equation_eq(
    gold: sp.Equality,
    target: sp.Equality,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    left_diff = sp.expand(gold.lhs - gold.rhs)
    right_diff = sp.expand(target.lhs - target.rhs)
    if sympy_expr_eq(left_diff, right_diff, float_rounding, numeric_precision, allow_set_relation_comp, strict):
        return True
    try:
        ratio = sp.cancel(left_diff / right_diff)
        if ratio.free_symbols:
            return False
        if ratio != 0 and ratio.is_finite:
            return True
    except Exception:
        pass
    return False


def _is_set_like(value: Basic | MatrixBase) -> bool:
    return isinstance(value, sp.Set)


def _set_like_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    left = _coerce_relation_to_set(gold)
    right = _coerce_relation_to_set(target)
    if not isinstance(left, sp.Set) or not isinstance(right, sp.Set):
        return False

    if type(left) is type(right) and left == right:
        return True

    if isinstance(left, sp.Interval) and isinstance(right, sp.Interval):
        return (
            left.left_open == right.left_open
            and left.right_open == right.right_open
            and sympy_expr_eq(left.start, right.start, float_rounding, numeric_precision, allow_set_relation_comp, strict)
            and sympy_expr_eq(left.end, right.end, float_rounding, numeric_precision, allow_set_relation_comp, strict)
        )

    if isinstance(left, sp.FiniteSet) and isinstance(right, sp.FiniteSet):
        return _unordered_items_eq(list(left), list(right), float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if isinstance(left, sp.Union) and isinstance(right, sp.Union):
        return _unordered_items_eq(list(left.args), list(right.args), float_rounding, numeric_precision, allow_set_relation_comp, strict)

    try:
        diff = left.symmetric_difference(right)
        if diff.is_empty is True:
            return True
    except Exception:
        pass

    return False


def _unordered_items_eq(
    gold_items: list[Basic | MatrixBase],
    target_items: list[Basic | MatrixBase],
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    if len(gold_items) != len(target_items):
        return False
    for ordering in permutations(range(len(target_items))):
        if all(
            sympy_expr_eq(
                gold_items[index],
                target_items[target_index],
                float_rounding,
                numeric_precision,
                allow_set_relation_comp,
                strict,
            )
            for index, target_index in enumerate(ordering)
        ):
            return True
    return False


def _is_relation_like(value: Basic | MatrixBase) -> bool:
    return isinstance(value, (Relational, Boolean))


def _relation_like_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    left_set = _coerce_relation_to_set(gold)
    right_set = _coerce_relation_to_set(target)
    if isinstance(left_set, sp.Set) and isinstance(right_set, sp.Set):
        return _set_like_eq(left_set, right_set, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    if isinstance(gold, Relational) and isinstance(target, Relational):
        return gold.canonical == target.canonical
    return False


def _coerce_relation_to_set(value: Basic | MatrixBase) -> Basic | MatrixBase:
    if isinstance(value, sp.Set):
        return value
    if isinstance(value, Relational):
        symbol = _single_free_symbol(value)
        if symbol is None:
            return value
        try:
            return sp.solve_univariate_inequality(value, symbol, relational=False)
        except Exception:
            return value
    if isinstance(value, And):
        sets = [_coerce_relation_to_set(arg) for arg in value.args]
        if all(isinstance(item, sp.Set) for item in sets):
            return sp.Intersection(*sets)
    if isinstance(value, Or):
        sets = [_coerce_relation_to_set(arg) for arg in value.args]
        if all(isinstance(item, sp.Set) for item in sets):
            return sp.Union(*sets)
    return value


def _single_free_symbol(value: Basic) -> sp.Symbol | None:
    symbols = sorted(value.free_symbols, key=lambda symbol: symbol.sort_key())
    return symbols[0] if len(symbols) == 1 else None


def _numeric_eq(gold: Basic | MatrixBase, target: Basic | MatrixBase, float_rounding: int, numeric_precision: int) -> bool:
    if not isinstance(gold, Basic) or not isinstance(target, Basic):
        return False
    try:
        if gold.free_symbols or target.free_symbols:
            return False
    except AttributeError:
        return False
    try:
        left = complex(sp.N(gold, numeric_precision))
        right = complex(sp.N(target, numeric_precision))
    except Exception:
        return False
    tolerance = 10 ** (-float_rounding)
    return abs(left - right) <= tolerance


def _is_simple_assignment_lhs(value: Basic) -> bool:
    return value.is_Symbol or value.is_Function

