"""Verification entry points."""

from __future__ import annotations

import sympy as sp
from sympy import Basic
from sympy.matrices import MatrixBase

from . import grader
from .errors import VerificationTimeoutError
from .utils import is_iterable_but_not_string, time_limit

ParsedValue = Basic | MatrixBase | str


def verify(
    gold: list[ParsedValue] | ParsedValue,
    target: list[ParsedValue] | ParsedValue,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: int | None = 5,
) -> bool:
    """Verify whether two parsed answers are mathematically equivalent."""

    gold_items = _coerce_items(gold)
    target_items = _coerce_items(target)
    if not gold_items or not target_items:
        return False

    for left in gold_items:
        for right in target_items:
            if _items_equal(
                left,
                right,
                float_rounding=float_rounding,
                numeric_precision=numeric_precision,
                strict=strict,
                allow_set_relation_comp=allow_set_relation_comp,
                timeout_seconds=timeout_seconds,
            ):
                return True

    combined_gold = _combine_items(gold_items)
    combined_target = _combine_items(target_items)
    if combined_gold is not None and combined_target is not None:
        return _items_equal(
            combined_gold,
            combined_target,
            float_rounding=float_rounding,
            numeric_precision=numeric_precision,
            strict=strict,
            allow_set_relation_comp=allow_set_relation_comp,
            timeout_seconds=timeout_seconds,
        )

    return False


def _items_equal(
    gold: ParsedValue,
    target: ParsedValue,
    *,
    float_rounding: int,
    numeric_precision: int,
    strict: bool,
    allow_set_relation_comp: bool,
    timeout_seconds: int | None,
) -> bool:
    if isinstance(gold, str) or isinstance(target, str):
        return str(gold).strip().lower() == str(target).strip().lower()

    try:
        with time_limit(timeout_seconds, VerificationTimeoutError, "Verification timed out"):
            return grader.sympy_expr_eq(
                gold,
                target,
                float_rounding=float_rounding,
                numeric_precision=numeric_precision,
                allow_set_relation_comp=allow_set_relation_comp,
                strict=strict,
            )
    except VerificationTimeoutError:
        return False


def _coerce_items(value: list[ParsedValue] | ParsedValue) -> list[ParsedValue]:
    if is_iterable_but_not_string(value):
        return list(value)
    return [value]


def _combine_items(items: list[ParsedValue]) -> Basic | MatrixBase | None:
    if len(items) < 2:
        return None
    normalized = []
    for item in items:
        if isinstance(item, str):
            return None
        if isinstance(item, MatrixBase):
            normalized.append(sp.ImmutableMatrix(item))
        else:
            normalized.append(item)
    try:
        return sp.FiniteSet(*normalized)
    except Exception:
        return None

