"""Convenience metric helpers."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

from .parser import DEFAULT_EXTRACTION_CONFIG, parse
from .verifier import verify


def math_metric(
    gold: Any,
    target: Any,
    *,
    extraction_config=DEFAULT_EXTRACTION_CONFIG,
    **verify_kwargs: Any,
) -> bool | float:
    """Compare a single pair or compute mean accuracy across sequences."""

    if _is_batch(gold, target):
        gold_items = list(gold)
        target_items = list(target)
        if not gold_items:
            return 0.0
        results = [
            math_metric(single_gold, single_target, extraction_config=extraction_config, **verify_kwargs)
            for single_gold, single_target in zip(gold_items, target_items)
        ]
        return float(sum(bool(result) for result in results) / len(results))

    gold_value = parse(gold, extraction_config) if isinstance(gold, str) else gold
    target_value = parse(target, extraction_config) if isinstance(target, str) else target
    return verify(gold_value, target_value, **verify_kwargs)


def _is_batch(gold: Any, target: Any) -> bool:
    return (
        isinstance(gold, Sequence)
        and isinstance(target, Sequence)
        and not isinstance(gold, (str, bytes))
        and not isinstance(target, (str, bytes))
    )

